sys_ui_action.client_script_v2:
function onClick(g_form) {
    if (g_form.getValue('comments') == '') {
        g_form.setMandatory('comments', true);
        g_modal.alert("Please add your comments before closing this task");
        return false;
    } else {

        g_modal.confirm("Do you want to approve this task?", function(confirmed) {
            if (confirmed == true) {
                var currentUser = g_user.userID;
                var makerUser = g_scratchpad.maker_sys_id;

                if (currentUser == makerUser) {
                    g_modal.alert("Same User Can not be Maker & Checker");
                    return;
                } else {
                    var comments = g_form.getValue('comments');
                    g_form.setValue('state', 3);
                    g_form.setValue('assigned_to', g_user.userID);
                    g_form.setValue('comments', comments);
                    g_form.save();
                    g_aw.closeRecord();
                    setTimeout(function() {
                        g_form.submit('approve');
                       var listURL = "/x/hsb11/mss-collateral-core/list/params/list-id/25e6a0771b32ea502ac120a8b04bcb3b"; 
                        var win = top.window.open(listURL, '_self');
                        win.focus();
                    }, 300);

                }
            } else {

                return false;
            }
        });

    }
}
